type Todo = { id: string; title: string; done: boolean }

export function TodoList({ todos }: { todos: Todo[] }) {
  return (
    <ul>
      {todos.map((todo, i) => (
        <li key={i}>
          <input type="checkbox" defaultChecked={todo.done} />
          {todo.title}
        </li>
      ))}
    </ul>
  )
}

